package com.bank.vertx;

import io.vertx.core.Vertx;
import java.util.logging.Logger;

public class BankApp {
    private static final Logger log = Logger.getLogger(BankApp.class.getName());

    public static void main(String[] args) {
        Vertx vertx = Vertx.vertx(); // creates event-loop + worker pools
        vertx.deployVerticle(new MainVerticle())
             .onSuccess(id -> log.info("Deployed MainVerticle id=" + id))
             .onFailure(err -> log.severe("Deploy failed: " + err.getMessage()));
    }
}
