package com.bank.vertx;

import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;

public class MainVerticle extends AbstractVerticle {
    @Override
    public void start(Promise<Void> startPromise) {
        // Deploy the account verticle as a WORKER (it may block), then the HTTP verticle.
        vertx.deployVerticle(new AccountVerticle(),
                new io.vertx.core.DeploymentOptions().setWorker(true))
             .compose(id -> vertx.deployVerticle(new HttpVerticle()))
             .onSuccess(id -> startPromise.complete())
             .onFailure(startPromise::fail);
    }
}
