package com.bank.vertx;

import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import java.util.logging.Logger;

public class HttpVerticle extends AbstractVerticle {
    private static final Logger log = Logger.getLogger(HttpVerticle.class.getName());

    @Override
    public void start(Promise<Void> startPromise) {
        vertx.createHttpServer().requestHandler(req -> {
            // Non-blocking: parse accountId, ask AccountVerticle over the event bus.
            String accountId = req.getParam("accountId"); // e.g. SAV2001
            log.info(() -> "HTTP balance request for " + accountId);
            vertx.eventBus().<String>request("account.balance", accountId)
                .onSuccess(reply -> req.response()
                        .putHeader("content-type", "application/json")
                        .end("{\"accountId\":\"" + accountId + "\",\"balance\":" + reply.body() + "}"))
                .onFailure(err -> req.response().setStatusCode(500).end("{\"error\":\"lookup failed\"}"));
        }).listen(8080)
          .onSuccess(s -> { log.info("HTTP on 8080"); startPromise.complete(); })
          .onFailure(startPromise::fail);
    }
}
