package com.bank.vertx;

import io.vertx.core.AbstractVerticle;
import java.math.BigDecimal;
import java.util.Map;
import java.util.logging.Logger;

// Worker verticle: allowed to block. Replies to event-bus balance requests.
public class AccountVerticle extends AbstractVerticle {
    private static final Logger log = Logger.getLogger(AccountVerticle.class.getName());
    private static final Map<String, BigDecimal> DB = Map.of(
        "SAV2001", new BigDecimal("1000000"),  // Rajesh
        "CUR3001", new BigDecimal("250000"));   // Priya

    @Override
    public void start() {
        vertx.eventBus().<String>consumer("account.balance", msg -> {
            String accountId = msg.body();
            // Simulated SLOW DB call moved off event loop with executeBlocking.
            vertx.executeBlocking(promise -> {
                try { Thread.sleep(100); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                BigDecimal bal = DB.getOrDefault(accountId, BigDecimal.ZERO);
                log.info(() -> "Looked up " + accountId + " = Rs." + bal);
                promise.complete(bal);
            }).onSuccess(bal -> msg.reply(bal.toString()))
              .onFailure(err -> msg.fail(500, "DB error"));
        });
        log.info("AccountVerticle consuming account.balance");
    }
}
